import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { environment } from '../../../environments/environment';

@Injectable({ providedIn: 'root' })
export class ProfService {
  private api = `${environment.apiUrl}/prof`;
  private classApi = `${environment.apiUrl}/classrooms`;

  constructor(private http: HttpClient) {}

  /** 🔐 Récupère les infos du prof connecté */
  me() {
    return this.http.get<any>(`${this.api}/me`);
  }

  /** 🌍 Liste de tous les profs pour espace étudiant */
  getAllProfs() {
    return this.http.get<any[]>(`${this.api}/all`);
  }

  /** 🏫 Liste des classes du prof connecté */
  getMyClasses() {
    return this.http.get<any[]>(`${this.classApi}`);
  }

  /** ➕ Crée une nouvelle classe */
  createClassroom(payload: { name: string; description?: string }) {
    return this.http.post(`${this.classApi}`, payload);
  }

  /** 🔎 Trouve une classe par son code d’accès */
  getClassByCode(code: string) {
    return this.http.get(`${this.classApi}/${code}`);
  }
}
